// Extract lead fields from the Notion trigger payload.
// Handles both simplified and raw Notion page objects.
const item = $input.first();
const props = item.json?.properties ?? item.json ?? {};

const getText = (prop) => {
  if (!prop) return '';
  if (typeof prop === 'string') return prop;
  if (prop.title?.[0]?.plain_text) return prop.title[0].plain_text;
  if (prop.rich_text?.[0]?.plain_text) return prop.rich_text[0].plain_text;
  if (prop.text?.[0]?.plain_text) return prop.text[0].plain_text;
  if (prop.url) return prop.url;
  if (prop.email) return prop.email;
  if (prop.select?.name) return prop.select.name;
  if (prop.formula?.string) return prop.formula.string;
  return '';
};

const name    = getText(props['Name']    ?? props['name'])    || 'Unknown';
const company = getText(props['Company'] ?? props['company']) || 'Unknown';
const linkedin= getText(props['LinkedIn URL'] ?? props['LinkedIn'] ?? props['linkedin_url']) || '';
const email   = getText(props['Email']   ?? props['email'])   || '';
const stage   = getText(props['Stage']   ?? props['stage'])   || 'Unknown';
const source  = getText(props['Source']  ?? props['source'])  || 'Unknown';
const notes   = getText(props['Notes']   ?? props['notes'])   || '';
const pageId  = item.json?.id ?? '';
const pageUrl = item.json?.url ?? '';

console.log('[LEO] New lead detected:', name, '@', company);

if (name === 'Unknown' && company === 'Unknown') {
  throw new Error('Lead page has no Name or Company. Check Notion CRM database fields match the expected names.');
}

return [{ json: { name, company, linkedin, email, stage, source, notes, pageId, pageUrl } }];

