// Parse the research JSON from the agent and validate all fields.
// Falls back gracefully with a partial profile if JSON is malformed.
const item = $input.first();
let raw = '';

if (typeof item?.json?.output === 'string') {
  raw = item.json.output;
} else if (Array.isArray(item?.json?.output)) {
  raw = item.json.output?.[0]?.content?.[0]?.text ?? '';
} else {
  raw = JSON.stringify(item?.json ?? {});
}

console.log('[LEO] Raw agent output length:', raw.length);
console.log('[LEO] Raw preview:', raw.substring(0, 200));

const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);

let parsed = null;
if (jsonMatch) {
  try {
    parsed = JSON.parse(jsonMatch[0]);
  } catch(e) {
    console.log('[LEO] JSON parse failed:', e.message);
  }
}

const safe = (val, fallback) =>
  (typeof val === 'string' && val.trim().length > 3) ? val.trim() : fallback;

const safeArr = (val, fallback) =>
  (Array.isArray(val) && val.length > 0) ? val : fallback;

const lead = $('Extract Lead Fields').item.json;

return [{
  json: {
    name:                lead.name,
    company:             lead.company,
    linkedin:            lead.linkedin,
    email:               lead.email,
    stage:               lead.stage,
    source:              lead.source,
    pageId:              lead.pageId,
    pageUrl:             lead.pageUrl,
    backgroundSummary:   safe(parsed?.backgroundSummary,   'No background data found. Research manually.'),
    companyIntel:        safe(parsed?.companyIntel,        'No company data found. Research manually.'),
    likelyPainPoints:    safeArr(parsed?.likelyPainPoints, ['To be identified in intro call']),
    conversationHooks:   safeArr(parsed?.conversationHooks, ['Ask about their current biggest challenge']),
    outreachMessage:     safe(parsed?.outreachMessage,     'Draft outreach message not generated. Write manually.'),
    researchConfidence:  safe(parsed?.researchConfidence,  'low'),
    sourcesFound:        safeArr(parsed?.sourcesFound,     []),
    rawOutput:           raw.substring(0, 800)
  }
}];

